import { HttpInterceptorFn } from '@angular/common/http';
import { inject } from '@angular/core';

export const authInterceptor: HttpInterceptorFn = (req, next) => {
  const token = inject(Session).token();
  if (!token) return next(req);
  // Every request gets Authorization, public reads included, so
  // none is eligible for the transfer cache: each is sent twice
  const headers = { Authorization: `Bearer ${token}` };
  return next(req.clone({ setHeaders: headers }));
};

import { HttpInterceptorFn } from '@angular/common/http';
import { inject } from '@angular/core';

export const authInterceptor: HttpInterceptorFn = (req, next) => {
  const token = inject(Session).token();
  // Catalog reads stay anonymous, so the server's responses are
  // serialized into the page and reused during hydration
  if (!token || req.url.includes('/api/catalog/')) return next(req);
  const headers = { Authorization: `Bearer ${token}` };
  return next(req.clone({ setHeaders: headers }));
};
